// before: settings (read only by a deep <DangerZone/>) drilled through 2 layout layers
-function SettingsPage({ settings }: { settings: Settings }) {
-  return <Layout><Panel><DangerZone settings={settings} /></Panel></Layout>;
-}

// after: 'no more drilling!'
+const SettingsContext = createContext<Settings | null>(null);
+export function SettingsProvider({ settings, children }: { settings: Settings; children: React.ReactNode }) {
+  return <SettingsContext.Provider value={settings}>{children}</SettingsContext.Provider>;
+}
+// mounted once, at the app root:
+// <SettingsProvider settings={settings}><App /></SettingsProvider>
+function DangerZone() {
+  const settings = useContext(SettingsContext)!;
+  return <section>{settings.dangerEnabled ? 'on' : 'off'}</section>;
+}
+// Layout and Panel already accept children, so SettingsPage just renders <DangerZone/>
